const test = require("node:test")
const assert = require("node:assert/strict")
const fs = require("node:fs")
const path = require("node:path")

const { parseContractErrors } = require("../src/parse.js")
const { analyze, summarize } = require("../src/analyze.js")
const { toMarkdown } = require("../src/registry.js")

/**
 * These fixtures and their expected output were generated by running the
 * actual codepact-core ESM modules at commit
 * efd2c2ffe7dd3d57a9823cd53262e96f48bfdb09, not by hand. See VENDORING.md.
 * If this test ever fails after a legitimate upstream change, regenerate
 * parity-expected.json from the new pinned commit rather than editing it
 * by hand.
 */
const cases = JSON.parse(
	fs.readFileSync(path.join(__dirname, "fixtures/parity-cases.json"), "utf8"),
)
const expected = JSON.parse(
	fs.readFileSync(path.join(__dirname, "fixtures/parity-expected.json"), "utf8"),
)

test("vendored parse/analyze match codepact-core's output exactly, fixture by fixture", () => {
	assert.equal(cases.length, expected.length)

	for (let i = 0; i < cases.length; i++) {
		const input = cases[i]
		const want = expected[i]
		assert.equal(input.name, want.name)

		const enums = parseContractErrors(input.source, input.file)
		const findings = analyze(enums)
		const counts = summarize(findings)

		assert.deepEqual(enums, want.enums, input.name + ": enums")
		assert.deepEqual(findings, want.findings, input.name + ": findings")
		assert.deepEqual(counts, want.counts, input.name + ": counts")
	}
})

test("qualified #[core::contracterror] attributes are recognised, not just the bare form", () => {
	const enums = parseContractErrors(
		["#[core::contracterror]", "pub enum E {", "    A = 1,", "}"].join("\n"),
		"e.rs",
	)
	assert.equal(enums.length, 1)
	assert.equal(enums[0].variants[0].value, 1)
})

test("an explicit discriminant this tool cannot evaluate is reported as unresolved, not implicit", () => {
	const enums = parseContractErrors(
		[
			"#[contracterror]",
			"pub enum E {",
			"    A = SOME_EXTERNAL_CONST,",
			"}",
		].join("\n"),
		"e.rs",
	)
	assert.equal(enums[0].variants[0].value, null)
	assert.equal(enums[0].variants[0].valueState, "unresolved")

	const findings = analyze(enums)
	assert.equal(findings.length, 0, "an unresolved code must not be reported as implicit")
})

test("the registry marks unresolved codes distinctly from implicit ones and adds a caveat", () => {
	const enums = parseContractErrors(
		[
			"#[contracterror]",
			"pub enum E {",
			"    A = SOME_EXTERNAL_CONST,",
			"    B,",
			"}",
		].join("\n"),
		"e.rs",
	)
	const findings = analyze(enums)
	const markdown = toMarkdown(enums, findings)

	assert.match(markdown, /_unresolved_/)
	assert.match(markdown, /_implicit_/)
	assert.match(markdown, /1 explicit discriminant\(s\) could not be resolved/)
})

test("a scan with only unresolved codes says so instead of a bare 'No issues found'", () => {
	const enums = parseContractErrors(
		["#[contracterror]", "pub enum E {", "    A = SOME_EXTERNAL_CONST,", "}"].join("\n"),
		"e.rs",
	)
	const markdown = toMarkdown(enums, analyze(enums))
	assert.match(markdown, /No issues found in resolved codes\./)
})

test("end to end: a qualified attribute with an unresolved discriminant is scanned and warned about, not skipped", () => {
	const { spawnSync } = require("node:child_process")
	const os = require("node:os")
	const actionPath = path.join(__dirname, "../src/action.js")

	const root = fs.mkdtempSync(path.join(os.tmpdir(), "codepact-parity-e2e-"))
	try {
		fs.writeFileSync(
			path.join(root, "error.rs"),
			[
				"#[core::contracterror]",
				"#[derive(Copy, Clone, Debug, Eq, PartialEq)]",
				"#[repr(u32)]",
				"pub enum E {",
				"    A = EXTERNAL_CONST,",
				"    B = 1,",
				"}",
			].join("\n"),
		)

		const result = spawnSync(process.execPath, [actionPath], {
			cwd: root,
			encoding: "utf8",
			timeout: 5000,
			env: {
				...process.env,
				INPUT_PATHS: ".",
				INPUT_SUMMARY: "false",
				INPUT_ANNOTATE: "true",
				GITHUB_OUTPUT: "",
				GITHUB_STEP_SUMMARY: "",
			},
		})

		assert.match(result.stdout, /scanned 1 enum/, "a qualified attribute must still be scanned")
		assert.match(result.stdout, /1 unresolved discriminant\(s\)/)
		assert.match(
			result.stdout,
			/::warning title=Codepact::1 explicit discriminant\(s\) use expressions this tool cannot evaluate/,
		)
	} finally {
		fs.rmSync(root, { recursive: true, force: true })
	}
})
